import {resetIceCreamMotion,disposeIceCreamMotion} from './ice-cream-motion.js';
import * as T from './vendor/three.module.js';
import {poseMotion} from './motions.js';
import {hideMotionProps} from './social-motion.js';
import {resetSleepMotion,disposeSleepMotion} from './sleep-motion.js';
import {moreDefaults} from './options.js';
import {faceTexture} from './face.js';
import {sculptHead,sculptFace,bindSoftLimb} from './sculpt.js';
import {buildSourceAvatar} from './source-avatar.js';
import {addGlasses} from './glasses.js';

export const defaults={...moreDefaults,name:'모찌',species:'cat',bodyColor:'#e4dacb',bellyColor:'#f6f0fd',eyeColor:'#70606d',accentColor:'#a78e7c',expression:'glossy',ears:1,head:1,body:1.2,legs:1,eyeSize:.92,tail:'curl',horns:false,halo:false,blush:true,glasses:false,hat:false,headset:false,filter:'lowpoly',motion:'float',speed:1.5,outline:false,detail:'low'};
export const palettes=[{name:'라벤더 밀크',bodyColor:'#d9cef0',bellyColor:'#f6f0fd',eyeColor:'#a88fda',accentColor:'#a4cbce'},{name:'피치 소다',bodyColor:'#efc8c9',bellyColor:'#fff0de',eyeColor:'#cf789e',accentColor:'#dfbc83'},{name:'민트 구름',bodyColor:'#c2dad0',bellyColor:'#f0f4df',eyeColor:'#6f9c90',accentColor:'#a09bcc'},{name:'버터 크림',bodyColor:'#e9dfb8',bellyColor:'#fff9e6',eyeColor:'#b09c65',accentColor:'#c89fb5'},{name:'블루 문',bodyColor:'#bed0eb',bellyColor:'#ecf4ff',eyeColor:'#7195c6',accentColor:'#c3b7e9'},{name:'밤의 조각',bodyColor:'#5f5e73',bellyColor:'#9b95ae',eyeColor:'#caacd6',accentColor:'#9bc7c5'}];
export const boneDefs=[['全ての親','Root',-1],['センター','Center',0],['下半身','Hips',1],['上半身','Spine',2],['首','Neck',3],['頭','Head',4],['左肩','LeftShoulder',3],['左腕','LeftArm',6],['左ひじ','LeftElbow',7],['左手首','LeftWrist',8],['右肩','RightShoulder',3],['右腕','RightArm',10],['右ひじ','RightElbow',11],['右手首','RightWrist',12],['左足','LeftLeg',2],['左ひざ','LeftKnee',14],['左足首','LeftAnkle',15],['右足','RightLeg',2],['右ひざ','RightKnee',17],['右足首','RightAnkle',18],['左足ＩＫ','LeftFootIK',0],['右足ＩＫ','RightFootIK',0]];

function earGeo(w,h,depth){const sh=new T.Shape();sh.moveTo(-w/2,0);sh.lineTo(w/2,0);sh.lineTo(w*.14,h);sh.lineTo(-w*.08,h*.92);sh.closePath();const g=new T.ExtrudeGeometry(sh,{depth,bevelEnabled:true,bevelThickness:.025,bevelSize:.02,bevelSegments:1,steps:1});g.translate(0,0,-depth/2);return g;}
export function buildAvatar(s){return buildSourceAvatar(s);}
export function buildProceduralAvatar(s){const root=new T.Group();root.name='PixelPals';root.userData.pixelPals={version:1,state:{...s}};const bones=boneDefs.map(([,name])=>{const b=new T.Bone();b.name=name;return b;});bones.forEach((b,i)=>{const p=boneDefs[i][2];(p<0?root:bones[p]).add(b);});const [base,center,hips,spine,neck,head]=bones;hips.position.y=.43*s.legs;spine.position.y=.15;neck.position.y=.39;head.position.y=.64;head.scale.setScalar(s.head*1.08); const seg=s.detail==='verylow'?6:s.detail==='high'?24:s.detail==='smooth'?20:10;const mat=(color,key)=>{const m=new T.MeshStandardMaterial({color,roughness:.82,metalness:0,flatShading:s.filter==='lowpoly'});if(key)m.userData.colorSetting=key;return m;};const fur=mat(s.bodyColor),belly=mat(s.bellySeparate?s.bellyColor:s.bodyColor),accent=mat(s.accentColor),dark=mat('#68627c'),cream=mat('#fff9ee');const materials=[fur,belly,accent,dark,cream];const softLimbs=[];let role='body';const earMat=s.earSeparate?mat(s.earColor):fur,armMat=s.armSeparate?mat(s.armColor):fur,hornMat=mat(s.hornsColor);
 function mesh(g,m,parent,pos=[0,0,0],scale=[1,1,1]){const obj=new T.Mesh(g,m);obj.position.fromArray(pos);obj.scale.fromArray(scale);obj.castShadow=true;obj.receiveShadow=true;obj.userData.role=role;parent.add(obj);return obj;}
 function ellipsoid(m,parent,pos,scale){return mesh(new T.SphereGeometry(1,seg,Math.max(5,seg/2)),m,parent,pos,scale);}
 function cylinder(m,parent,pos,r1,r2,len){return mesh(new T.CylinderGeometry(r1,r2,len,seg),m,parent,pos);}
 const torso=mesh(new T.LatheGeometry([new T.Vector2(.21,-.2),new T.Vector2(.31,-.13),new T.Vector2(.35,.10),new T.Vector2(.29,.32),new T.Vector2(.17,.4)],seg),fur,spine,[0,0,0],[s.body,1,.86]);ellipsoid(belly,spine,[0,.06,.252],[.21*s.body,.27,.055]);cylinder(fur,neck,[0,-.005,0],.15,.16,.16);const sculpted=mesh(sculptHead(s.detail),fur,head);sculpted.name='SculptHead';const face=mesh(sculptFace(),new T.MeshBasicMaterial({map:faceTexture(s),transparent:true,alphaTest:.1,side:T.DoubleSide}),head,[0,-.04,0]);face.name='Face';face.castShadow=false;
 for(const [side,offset] of [[1,6],[-1,10]]){const shoulder=bones[offset],arm=bones[offset+1],elbow=bones[offset+2],wrist=bones[offset+3];shoulder.position.set(side*.27*s.body,.28,0);arm.position.set(side*.025,0,0);arm.rotation.z=side*.53;arm.userData.restRotation=arm.quaternion.clone();elbow.position.y=-.17;wrist.position.y=-.12;softLimbs.push({mesh:ellipsoid(armMat,arm,[0,-.13,0],[.14,.235,.145]),upper:offset+1,lower:offset+2});}
 for(const [side,offset] of [[1,14],[-1,17]]){const leg=bones[offset],knee=bones[offset+1],ankle=bones[offset+2];leg.position.set(side*.18,-.06,0);knee.position.y=-.14*s.legs;ankle.position.y=-.14*s.legs;softLimbs.push({mesh:ellipsoid(fur,leg,[0,-.12*s.legs,.025],[.15,.225*s.legs,.165]),upper:offset,lower:offset+1});bones[side===1?20:21].position.set(side*.18,.09,0);}
 role='ears';for(const side of [-1,1]){if(['cat','fox','wolf'].includes(s.species)){const tall=s.species==='fox'?1.4:s.species==='wolf'?1.17:1;const outer=mesh(earGeo(.58,.76*s.ears*tall,.22),earMat,head,[side*.52,.5,-.03]);outer.rotation.z=-side*.16;}else if(s.species==='bunny'){const outer=ellipsoid(earMat,head,[side*.4,.85+(.15*s.ears),-.015],[.19,.53*s.ears,.17]);outer.userData.ear=true;outer.rotation.z=-side*.14;}else if(['bear','mouse','hamster','raccoon','otter'].includes(s.species)){const radius={bear:.25,mouse:.32,hamster:.20,raccoon:.22,otter:.17}[s.species]*s.ears;ellipsoid(earMat,head,[side*.62,.63,0],[radius,radius,.16]);}else if(['deer','antler'].includes(s.species)){const ear=ellipsoid(earMat,head,[side*.73,.58,0],[.16,.34*s.ears,.12]);ear.rotation.z=-side*.75;if(s.species==='antler'){const paths=[[[side*.3,.54,-.1],[side*.36,.95,-.15],[side*.29,1.2,-.13]],[[side*.36,.95,-.15],[side*.58,1.13,-.15]]];for(const p of paths)mesh(new T.TubeGeometry(new T.CatmullRomCurve3(p.map(x=>new T.Vector3(...x))),6,.039,5,false),hornMat,head);}}else if(s.species==='axolotl'){for(let i=0;i<3;i++){const g=mesh(new T.ConeGeometry(.11,.38*s.ears,5),earMat,head,[side*.88,.32-i*.26,0]);g.rotation.z=-side*(.7+i*.5);}}else if(['puppy','lop'].includes(s.species)){const long=s.species==='lop'?1.45:1;const outer=ellipsoid(earMat,head,[side*.79,.0,.015],[.22,.40*s.ears*long,.17]);outer.rotation.z=side*.20;}}
 role='horns';if(s.horns)for(const side of [-1,1]){const obj=mesh(new T.ConeGeometry(.085,.27,6),hornMat,head,[side*.28,.67,.28]);obj.rotation.z=-side*.18;}
 role='halo';if(s.halo){const halo=mesh(new T.TorusGeometry(.44,.033,4,18),mat(s.haloColor),head,[0,s.species==='bunny'?1.65:1.23,0]);halo.rotation.x=Math.PI/2;halo.rotation.z=.11;halo.name='Halo';}
 role='tail';if(s.tail!=='none'){if(s.tail==='puff')ellipsoid(belly,hips,[0,-.03,-.41],[.19,.19,.19]);else if(s.tail==='stub')ellipsoid(accent,hips,[0,.03,-.5],[.13,.13,.3]);else{const pts=[new T.Vector3(0,.04,-.23),new T.Vector3(.32,0,-.34),new T.Vector3(.62,-.03,-.27),new T.Vector3(.80,.035,-.20),new T.Vector3(.96,.135,-.16)];mesh(new T.TubeGeometry(new T.CatmullRomCurve3(pts),16,s.tail==='fluffy'?.14:.065,s.tail==='fluffy'?6:8,false),fur,hips);ellipsoid(s.tail==='fluffy'?belly:fur,hips,[.96,.135,-.16],s.tail==='fluffy'?[.15,.14,.13]:[.065,.065,.065]);}}
 role='ribbon';if(s.ribbon!=='none'){const ribbonMat=mat(s.ribbonColor);const bow=(parent,pos)=>{const group=new T.Group();parent.add(group);group.position.fromArray(pos);group.scale.setScalar(s.ribbonSize);for(const side of[-1,1]){const tri=mesh(new T.ConeGeometry(.14,.23,3),ribbonMat,group,[side*.12,0,0]);tri.rotation.z=side*Math.PI/2;tri.rotation.y=Math.PI/2;}ellipsoid(cream,group,[0,0,.025],[.045,.055,.055]);};if(['left','both'].includes(s.ribbon))bow(head,[-.56,.56,.29]);if(['right','both'].includes(s.ribbon))bow(head,[.56,.56,.29]);if(s.ribbon==='top')bow(head,[0,.67,.13]);if(s.ribbon==='neck')bow(neck,[0,0,.22]);if(s.ribbon==='chest')bow(spine,[0,.23,.28]);}
 role='glasses';if(s.glasses)addGlasses(head,s);
 role='hat';if(s.hat){const cap=ellipsoid(accent,head,[0,.66,0],[.79,.22,.58]);mesh(new T.CylinderGeometry(.79,.82,.075,12),accent,head,[0,.60,0],[1,1,.71]);ellipsoid(cream,head,[.21,.9,.01],[.075,.09,.075]);}
 role='headset';if(s.headset){const headsetMat=mat(s.headsetColor,'headsetColor');const band=mesh(new T.TorusGeometry(.91,.07,5,16,Math.PI),dark,head,[0,.14,0]);for(const side of [-1,1]){const cup=cylinder(headsetMat,head,[side*.90,.13,.025],.24,.24,.16);cup.rotation.z=Math.PI/2;const cushion=cylinder(dark,head,[side*.79,.13,.025],.20,.20,.09);cushion.rotation.z=Math.PI/2;}const mic=mesh(new T.TubeGeometry(new T.CatmullRomCurve3([new T.Vector3(.97,.08,.04),new T.Vector3(.87,-.22,.42),new T.Vector3(.42,-.28,.57)]),8,.024,4,false),dark,head);ellipsoid(headsetMat,head,[.41,-.28,.57],[.065,.035,.035]);}
 root.updateMatrixWorld(true);softLimbs.forEach(l=>bindSoftLimb(l.mesh,root,bones,l.upper,l.lower));bones.forEach(b=>{b.userData.restPosition=b.position.clone();b.userData.restQuaternion=b.quaternion.clone();});const outline=[];if(s.outline)root.traverse(obj=>{if(obj.isMesh&&obj.name!=='Face'){const line=new T.Mesh(obj.geometry,new T.MeshBasicMaterial({color:s.outlineColor,side:T.BackSide}));line.scale.setScalar(1+s.outlineWidth);line.userData.outline=true;outline.push([obj,line]);}});outline.forEach(([obj,line])=>obj.add(line));return{root,bones,materials,face,rest:boneDefs.map((_,i)=>bones[i].getWorldPosition(new T.Vector3()))};}
export function disposeAvatar(avatar){disposeIceCreamMotion(avatar);disposeSleepMotion(avatar);const gs=new Set(),ms=new Set(),ts=new Set(),ss=new Set();avatar.root.traverse(o=>{if(o.geometry)gs.add(o.geometry);if(o.skeleton)ss.add(o.skeleton);for(const m of Array.isArray(o.material)?o.material:[o.material])if(m){ms.add(m);if(m.map)ts.add(m.map);}});gs.forEach(x=>x.dispose());ms.forEach(x=>x.dispose());ts.forEach(x=>x.dispose());ss.forEach(x=>x.dispose());}
export function resetPose(a){hideMotionProps(a);resetIceCreamMotion(a);resetSleepMotion(a);a.bones.forEach(b=>{b.position.copy(b.userData.restPosition);b.quaternion.copy(b.userData.restQuaternion);});}
export const poseAvatar=poseMotion;

export function collectModel(a){resetPose(a);a.root.position.set(0,0,0);a.root.rotation.set(0,0,0);a.root.updateMatrixWorld(true);const vertices=[],normals=[],uvs=[],indices=[],weights=[],skinIndices=[],skinWeights=[],materials=[],groups=[];const materialIndex=new Map();const boneIndex=new Map(a.bones.map((b,i)=>[b,i]));a.root.traverse(o=>{if(!o.isMesh||o.userData.outline)return;for(let ancestor=o;ancestor;ancestor=ancestor.parent)if(ancestor.userData.motionProp)return;let node=o;while(node&&!boneIndex.has(node))node=node.parent;const bi=boneIndex.get(node)??0;const geo=o.geometry;const pos=geo.attributes.position;const norm=geo.attributes.normal;const uv=geo.attributes.uv;const start=vertices.length/3;const nm=new T.Matrix3().getNormalMatrix(o.matrixWorld);for(let i=0;i<pos.count;i++){const v=new T.Vector3().fromBufferAttribute(pos,i);if(o.isSkinnedMesh){o.skeleton.update();o.applyBoneTransform(i,v);}v.applyMatrix4(o.matrixWorld);const n=new T.Vector3().fromBufferAttribute(norm,i).applyMatrix3(nm).normalize();vertices.push(...v.toArray());normals.push(...n.toArray());uvs.push(uv?.getX(i)||0,uv?.getY(i)||0);weights.push(geo.attributes.skinIndex?.getX(i)??bi);for(let k=0;k<4;k++){skinIndices.push(geo.attributes.skinIndex?.array[i*4+k]??(k===0?bi:0));skinWeights.push(geo.attributes.skinWeight?.array[i*4+k]??(k===0?1:0));}}const ii=geo.index?Array.from(geo.index.array):Array.from({length:pos.count},(_,i)=>i);const mats=Array.isArray(o.material)?o.material:[o.material],ranges=Array.isArray(o.material)?geo.groups:[{start:0,count:ii.length,materialIndex:0}];for(const range of ranges){const mat=mats[range.materialIndex];let mi=materialIndex.get(mat);if(mi===undefined){mi=materials.length;materials.push(mat);materialIndex.set(mat,mi);groups.push([]);}groups[mi].push(...ii.slice(range.start,range.start+range.count).map(x=>x+start));}});const ranges=[];groups.forEach((g,i)=>{ranges.push({start:indices.length,count:g.length,materialIndex:i});indices.push(...g);});return{vertices,normals,uvs,indices,weights,skinIndices,skinWeights,materials,ranges,bonePositions:a.bones.map(b=>b.getWorldPosition(new T.Vector3()).toArray())};}
export function skinnedAvatar(a,s){const data=collectModel(a);const root=new T.Group();root.name='PixelPals';root.userData.pixelPals={version:1,state:{...s}};const bones=a.bones.map(b=>{const x=new T.Bone();x.name=b.name;x.position.copy(b.userData.restPosition);x.quaternion.copy(b.userData.restQuaternion);x.scale.copy(b.scale);return x;});bones.forEach((b,i)=>{const p=boneDefs[i][2];(p<0?root:bones[p]).add(b);});const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(data.vertices,3));geometry.setAttribute('normal',new T.Float32BufferAttribute(data.normals,3));geometry.setAttribute('uv',new T.Float32BufferAttribute(data.uvs,2));geometry.setIndex(data.indices);geometry.setAttribute('skinIndex',new T.Uint16BufferAttribute(data.skinIndices,4));geometry.setAttribute('skinWeight',new T.Float32BufferAttribute(data.skinWeights,4));data.ranges.forEach(g=>geometry.addGroup(g.start,g.count,g.materialIndex));const mesh=new T.SkinnedMesh(geometry,data.materials);root.add(mesh);root.updateMatrixWorld(true);mesh.bind(new T.Skeleton(bones));return{root,bones,geometry};}
